// Atualiza UM contato na tabela de contatos do Flow (API), achado pelo telefone (últimos 8 dígitos)
// ou pelo LinkedIn. Não mexe nos outros contatos da empresa.
const FLOW = 'https://vclwmydunloeqomsmaah.supabase.co/functions/v1/api-v1';
const H = { Authorization: '***REMOVIDO***', 'Content-Type': 'application/json' };
const http = (o) => this.helpers.httpRequest({ json: true, headers: H, ...o });

const ent = $('Recebe dados').first().json;
let campos = ent.campos;
if (typeof campos === 'string') { try { campos = JSON.parse(campos); } catch (e) { campos = {}; } }
campos = campos || {};
const last8 = v => String(v || '').replace(/\D/g, '').slice(-8);
const normLi = u => String(u || '').trim().toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/\/+$/, '');

const lista = ((await http({ method: 'GET', url: FLOW + '/leads/' + ent.lead_id + '/contacts' })).items) || [];
const alvo = lista.find(c =>
  (ent.telefone && last8(c.whatsapp).length === 8 && last8(c.whatsapp) === last8(ent.telefone)) ||
  (ent.linkedin && c.linkedin && normLi(c.linkedin) === normLi(ent.linkedin)));

let atualizado = null;
if (alvo) {
  atualizado = (await http({ method: 'PATCH', url: FLOW + '/contacts/' + alvo.id, body: campos })).contact;
}

const depois = lista.map(c => (alvo && c.id === alvo.id) ? (atualizado || { ...c, ...campos }) : c);
const comCanal = depois.filter(c => c && (c.whatsapp || c.linkedin));
const todosNaoContatar = comCanal.length > 0 && comCanal.every(c => c.contato_status === 'nao_contatar');
return [{ json: { lead_id: ent.lead_id, contact_id: alvo ? alvo.id : null, achou_contato: !!alvo, todos_nao_contatar: todosNaoContatar } }];

